import { applyHueSwap } from '@/render/HueSwap';
import {
  ACESFilmicToneMapping, Color, DirectionalLight, Fog, HemisphereLight, PCFSoftShadowMap, PerspectiveCamera, Scene, Vector3,
  WebGLRenderer,
} from 'three';
import { Input } from './Input';
import { isTouchDevice, TouchControls } from './TouchControls';
import { ASSET_BASE, loadAssets, type LoadedAssets } from './Assets';
import { Autopilot, AUTOPILOT_PROFILES, type AutopilotProfile } from '@/dev/Autopilot';
import * as SkeletonUtils from 'three/examples/jsm/utils/SkeletonUtils.js';
import { Sfx } from './Sfx';
import type { GameContext } from './Context';
import { GreyboxMap } from '@/world/GreyboxMap';
import { NavGrid } from '@/ai/NavGrid';
import { Fx } from '@/render/Fx';
import { PostFx } from '@/render/PostFx';
import { Hud } from '@/ui/Hud';
import { Player } from '@/entities/Player';
import type { Bot } from '@/entities/Bot';
import { Mission, MISSION_START } from '@/world/Mission';
import { HealthPack } from '@/world/HealthPack';
import type { Projectile } from '@/combat/Projectile';
import { DIFFICULTIES, type DifficultyId } from '@/data/difficulty';
import { DEATH_CAM_SECONDS, SCORE } from '@/data/rules';
import type { Hittable } from '@/combat/Hitscan';

type GameState = 'menu' | 'playing' | 'paused' | 'dead' | 'ended';

const FIXED_DT = 1 / 60;
// Fill light (sky hemisphere + environment map). Outdoors it is kept low so the sunlit and shaded sides of props differ
// clearly; inside the control block the sun never reaches, so the fill goes back up as the camera enters.
const FILL_OUT = { hemi: 0.42, env: 0.7 };
const FILL_IN = { hemi: 0.62, env: 1.0 };
/** 뷰모델(총·팔) 전용 수직 FOV */

export class Game {
  private readonly renderer: WebGLRenderer;
  private readonly scene = new Scene();
  private readonly camera: PerspectiveCamera;
  private readonly input: Input;
  private readonly hud = new Hud();
  private readonly sfx = new Sfx();
  private readonly fx: Fx;
  private readonly map = new GreyboxMap();
  private nav: NavGrid;
  private sun!: DirectionalLight;
  private hemi!: HemisphereLight;
  private indoor = 0;
  private readonly player: Player;
  private readonly bots: Bot[] = [];
  private readonly packs: HealthPack[] = [];
  private projectiles: Projectile[] = [];
  private readonly ctx: GameContext;

  private state: GameState = 'menu';
  /** 시작 화면에서 전체 화면을 골랐는가(Esc로 풀려도 재개할 때 다시 들어간다) */
  private wantFullscreen = false;
  private difficultyId: DifficultyId = 'normal';
  /** 터치 조작(모바일). 터치 기기가 아니면 null */
  private touch: TouchControls | null = null;
  readonly mission: Mission;
  private simTime = 0;
  private accumulator = 0;
  private lastFrame = 0;
  private score = 0;
  /** 쓰러진 뒤 결과 화면을 띄울 시각(부활은 없다) */
  private endAt = 0;
  /** 후처리(블룸·화면 보정). 만들지 못하는 환경이면 null → 기존처럼 화면에 바로 그린다. F7로 켜고 끈다 */
  private post: PostFx | null = null;
  /** 피격 화면 충격 계산용: 직전 프레임의 체력 */
  private lastHpSeen = 0;
  /** 후처리 자동 끄기 판정: 플레이 중 프레임 시간 누적 (한 번만 판정) */
  private perfFrames = 0;
  private perfTime = 0;
  private perfChecked = false;
  private debug = false;
  private startedAt = 0;
  assets: LoadedAssets | null = null;
  /** F8 오토파일럿 (플레이테스트/데모) */
  autopilot: Autopilot | null = null;

  constructor(container: HTMLElement) {
    this.renderer = new WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    const mobile = isTouchDevice();
    // 모바일은 화면 픽셀이 촘촘해 그대로 그리면 너무 무겁다 → 배율을 낮춘다
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, mobile ? 1.5 : 2));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = PCFSoftShadowMap;
    this.renderer.toneMapping = ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.2;
    container.appendChild(this.renderer.domElement);

    this.camera = new PerspectiveCamera(80, window.innerWidth / window.innerHeight, 0.05, 400);
    this.scene.add(this.camera);
    try {
      this.post = new PostFx(this.renderer, () => this.drawWorld(), () => this.drawViewmodel());
    } catch (e) {
      console.warn('[PostFx] 후처리를 만들 수 없어 끔', e);
      this.post = null;
    }
    this.scene.background = new Color(0x9fc5ff);
    this.scene.fog = new Fog(0x9fc5ff, 60, 240);

    // 늦은 오후 느낌: 낮고 따뜻한 해 + 약한 하늘빛. 해가 닿는 면과 그늘의 대비가 커지고 그림자가 길어진다
    const hemi = new HemisphereLight(0xd6e6ff, 0x6a5c4c, FILL_OUT.hemi);
    const sun = new DirectionalLight(0xffe0b0, 3.3);
    this.scene.environmentIntensity = FILL_OUT.env;
    sun.position.set(42, 40, 16);
    sun.castShadow = true;
    sun.shadow.mapSize.set(mobile ? 1024 : 2048, mobile ? 1024 : 2048);
    sun.shadow.camera.left = -52;
    sun.shadow.camera.right = 52;
    sun.shadow.camera.top = 46;
    sun.shadow.camera.bottom = -46;
    sun.shadow.camera.near = 10;
    sun.shadow.camera.far = 150;
    sun.shadow.bias = -0.0005;
    hemi.layers.enable(Player.VIEWMODEL_LAYER);
    sun.layers.enable(Player.VIEWMODEL_LAYER);
    this.scene.add(hemi, sun, sun.target);
    this.sun = sun;
    this.hemi = hemi;

    this.scene.add(this.map.group);
    // 관제동 실내 조명: 점광원은 모든 재질의 셰이더 비용을 올리므로 모바일에서는 넣지 않는다(천장 조명판의 발광만 보인다)
    if (!mobile) {
      for (const l of this.map.interiorLights) {
        l.layers.enable(Player.VIEWMODEL_LAYER);
        this.scene.add(l);
      }
    }
    this.nav = new NavGrid(this.map, MISSION_START);
    this.fx = new Fx(this.scene);
    this.fx.enableViewmodelLayer();
    this.input = new Input(this.renderer.domElement);
    this.player = new Player(this.map.colliders, this.camera);
    this.scene.add(this.player.hitGroup);
    for (const spot of this.map.healthPackSpots) {
      const pack = new HealthPack(spot.pos, spot.big);
      this.packs.push(pack);
      this.scene.add(pack.group);
    }

    const self = this;
    this.ctx = {
      scene: this.scene,
      camera: this.camera,
      map: this.map,
      nav: this.nav,
      fx: this.fx,
      hud: this.hud,
      sfx: this.sfx,
      get input() { return self.autopilot ?? self.input; },
      get difficulty() { return DIFFICULTIES[self.difficultyId]; },
      player: this.player,
      bots: this.bots,
      packs: this.packs,
      get assets() { return self.assets; },
      now: 0,
      get debug() { return self.debug; },
      hittables: (): Hittable[] => [this.player, ...this.bots],
      onBotKilled: (bot, headshot) => this.onBotKilled(bot, headshot),
      onPlayerDied: (by) => this.onPlayerDied(by),
      onNoise: (pos, radius) => this.onNoise(pos, radius),
      spawnProjectile: (p) => this.projectiles.push(p),
    };
    this.player.ctx = this.ctx;

    this.mission = new Mission(this.ctx, {
      onScore: (points, text) => {
        this.score += points;
        this.hud.setScore(this.score);
        this.hud.killFeed(`${text} +${points}`, 'hs');
      },
      onVictory: () => this.endGame(true),
      onDefeat: (reason) => this.endGame(false, reason),
      setGate: (open) => this.setGate(open),
      setDoor: (open) => this.setDoor(open),
    });

    if (mobile) {
      document.body.classList.add('touch');
      // The rotate hint can be dismissed: some app views stay in portrait.
      const hint = document.getElementById('rotate-hint');
      hint?.addEventListener('click', () => { hint.style.display = 'none'; });
      this.input.touchMode = true;
      this.touch = new TouchControls(this.input, () => this.input.releaseTouch(), () => {
        this.player.setThirdPerson(!this.player.thirdPerson);
      });
      // 후처리는 모바일 그래픽 칩에 부담이 커서 기본으로 끈다
      if (this.post) this.post.enabled = false;
      this.perfChecked = true;
    }

    this.bindUi();
    window.addEventListener('resize', () => this.onResize());
    this.input.onLockChange = (locked) => this.onLockChange(locked);
    this.input.onLockFailed = () => this.hud.killFeed('이 브라우저는 Pointer Lock을 지원하지 않아 마우스 시점이 동작하지 않습니다', 'death');
    this.player.spawn(MISSION_START, 0);
    this.hud.showOverlay('ov-menu');
    requestAnimationFrame((t) => this.frame(t));
    void this.loadAssets();
  }

  /** M3 에셋 로드: 실패하거나 없으면 그레이박스 유지 */
  private async loadAssets(): Promise<void> {
    const startBtn = document.getElementById('btn-start') as HTMLButtonElement | null;
    try {
      if (startBtn) startBtn.textContent = '에셋 로딩 중…';
      const a = await loadAssets();
      this.assets = a;
      if (a.sky) {
        this.scene.background = a.sky;
        this.scene.environment = a.sky;
        this.scene.fog = new Fog(0xc9dcf5, 60, 240);
      }
      this.map.applyTextures(a.floor, a.container, { floorN: a.floorN, deck: a.deck, deckN: a.deckN });
      if (a.mapKit) this.map.applyKit(a.mapKit);
      if (a.rifle) this.player.applyRifleModel(a.rifle);
      if (a.fpDirect) this.player.applyFpDirect(a.fpDirect);
      else if (a.fpDetail) this.player.applyFpDetail(a.fpDetail.scene, a.fpDetail.clips);
      else if (a.fpRig) this.player.applyFpRig(a.fpRig.scene, a.fpRig.clips);
      else if (a.fpArms) this.player.applyFpArmsModel(a.fpArms);
      if (a.player) this.scene.add(this.player.applyBody(a.player.scene, a.player.clips, a.rifle));
      this.fx.setTextures(a.vfx);
      this.fx.setModels(a.fxModels);
      this.warmupShaders(a);
      const clips = await this.sfx.loadBank(ASSET_BASE, this.camera);
      console.info(`[Assets] sfx clips: ${clips}`);
      console.info('[Assets] loaded', { sky: !!a.sky, floor: !!a.floor, container: !!a.container, raven: !!a.raven, clips: a.raven ? Object.keys(a.raven.clips) : [], rifle: !!a.rifle });
    } catch (e) {
      console.warn('[Assets] load failed, keeping greybox', e);
    } finally {
      if (startBtn) startBtn.textContent = '클릭하여 시작';
      // 로드 전 민짜 장면이 비치지 않도록 불투명했던 메뉴를 반투명으로
      document.getElementById('ov-menu')?.classList.remove('loading');
    }
  }

  // ---------- UI ----------

  private bindUi(): void {
    const diffBtns = document.querySelectorAll<HTMLButtonElement>('#difficulty .btn');
    diffBtns.forEach((b) =>
      b.addEventListener('click', () => {
        diffBtns.forEach((x) => x.classList.remove('sel'));
        b.classList.add('sel');
        this.difficultyId = (b.dataset.d as DifficultyId) ?? 'normal';
      }),
    );
    document.getElementById('btn-start')?.addEventListener('click', () => {
      if (this.touch) {
        // 모바일: 전체 화면·가로 고정을 시도한다(지원하지 않는 브라우저에서는 그냥 넘어간다)
        const el = document.documentElement as HTMLElement & { requestFullscreen?: () => Promise<void> };
        void el.requestFullscreen?.().then(() => (screen.orientation as unknown as { lock?: (o: string) => Promise<void> }).lock?.('landscape')).catch(() => undefined);
      }
      this.startGame();
    });
    document.getElementById('btn-restart')?.addEventListener('click', () => this.startGame());
    document.getElementById('btn-resume')?.addEventListener('click', () => this.input.requestLock());
    // 오버레이 자체 클릭으로도 재개
    document.getElementById('ov-pause')?.addEventListener('click', () => this.input.requestLock());
    this.bindTabGuard();
  }

  /**
   * Ctrl(앉기)을 누른 채 W를 누르면 브라우저가 탭을 닫는다(Ctrl+W). 페이지에서 이 단축키를 막을 방법은 없어서 두 겹으로 대비한다.
   *  1. 진행 중인 판이 있으면 닫히기 전에 브라우저의 확인 창이 뜨게 한다(취소하면 판이 그대로 남는다).
   *  2. 전체 화면에서는 키보드 잠금(Keyboard Lock, Chrome·Edge)으로 Ctrl+W·T·N을 게임이 받는다 → 창이 뜨지도 않는다.
   *     전체 화면은 시작 화면의 버튼으로 켠다(F11 전체 화면에서는 키보드 잠금이 동작하지 않는다).
   */
  private bindTabGuard(): void {
    window.addEventListener('beforeunload', (e) => {
      const inGame = this.state === 'playing' || this.state === 'paused' || this.state === 'dead';
      if (!inGame || this.autopilot || this.touch) return;
      e.preventDefault();
      e.returnValue = '';
    });
    const btn = document.getElementById('btn-fs');
    const kb = (navigator as Navigator & { keyboard?: { lock?: (keys?: string[]) => Promise<void>; unlock?: () => void } }).keyboard;
    const enter = (): void => {
      if (!this.wantFullscreen || document.fullscreenElement) return;
      void document.documentElement.requestFullscreen?.().catch(() => undefined);
    };
    btn?.addEventListener('click', () => {
      this.wantFullscreen = !document.fullscreenElement;
      if (this.wantFullscreen) enter();
      else void document.exitFullscreen?.().catch(() => undefined);
    });
    // Esc는 전체 화면과 마우스 잠금을 함께 푼다 → 다시 시작·재개할 때 전체 화면으로 돌아간다
    for (const id of ['btn-start', 'btn-restart', 'btn-resume', 'ov-pause']) document.getElementById(id)?.addEventListener('click', enter);
    document.addEventListener('fullscreenchange', () => {
      const on = !!document.fullscreenElement;
      if (btn) btn.textContent = on ? '전체 화면 끄기' : '전체 화면으로 하기';
      // Escape는 잠그지 않는다(일시정지에 쓴다). 게임이 쓰는 글자 키만 잠가서 Ctrl 조합이 브라우저로 가지 않게 한다
      if (on) void kb?.lock?.(['KeyW', 'KeyA', 'KeyS', 'KeyD', 'KeyT', 'KeyN', 'KeyR', 'KeyF', 'KeyE', 'KeyQ', 'KeyC', 'KeyV'])?.catch(() => undefined);
      else kb?.unlock?.();
    });
  }

  private onResize(): void {
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.post?.resize();
  }

  private onLockChange(locked: boolean): void {
    if (locked) {
      if (this.state === 'paused') {
        this.state = 'playing';
        this.hud.showOverlay(null);
      }
    } else if ((this.state === 'playing' || this.state === 'dead') && !this.autopilot) {
      this.state = 'paused';
      this.hud.showOverlay('ov-pause');
    }
  }

  // ---------- 흐름 ----------

  /** 관문을 여닫고 길찾기 격자를 다시 만든다. 닫혀 있으면 시작 자리(관제동)가 있는 북쪽만 도달 가능 영역이 된다 */
  private setGate(open: boolean): void {
    if (this.map.gateOpen === open) return;
    this.map.setGate(open);
    this.nav = new NavGrid(this.map, MISSION_START);
    this.ctx.nav = this.nav;
  }

  /** 관제동 정문을 여닫고 길찾기 격자를 다시 만든다. 닫혀 있으면 관제동 안만 도달 가능 영역이 된다 */
  private setDoor(open: boolean): void {
    if (this.map.doorOpen === open) return;
    this.map.setDoor(open);
    this.nav = new NavGrid(this.map, MISSION_START);
    this.ctx.nav = this.nav;
  }

  private startGame(): void {
    this.sfx.init();
    this.setGate(false);
    this.setDoor(false);
    for (const b of this.bots) {
      this.scene.remove(b.group, b.debugLine);
    }
    this.bots.length = 0;
    this.fx.clear();
    for (const pk of this.packs) pk.reset();
    for (const pr of this.projectiles) pr.dispose();
    this.projectiles = [];
    this.hud.resetFeeds();
    this.score = 0;
    this.simTime = 0;
    this.ctx.now = 0;
    this.startedAt = 0;
    this.player.resetStats();
    this.player.spawn(MISSION_START, 0);
    this.hud.setScore(this.score);
    this.hud.setVisible(true);
    this.hud.showOverlay(null);
    this.state = 'playing';
    this.mission.start();
    this.input.requestLock();
  }

  private onBotKilled(bot: Bot, headshot: boolean): void {
    const s = this.player.stats;
    s.kills++;
    s.streak++;
    s.maxStreak = Math.max(s.maxStreak, s.streak);
    this.score += bot.isBoss ? SCORE.bossKill : headshot ? SCORE.headshotKill : SCORE.kill;
    this.hud.setScore(this.score);
    this.hud.killFeed(`YOU ▶ ${bot.displayName}${headshot ? ' (헤드샷)' : ''}${bot.isBoss ? ' +500' : ''}`, headshot || bot.isBoss ? 'hs' : '');
    if (bot.isBoss) this.hud.setBoss(null);
    if (headshot) this.hud.headshotBanner();
    this.sfx.kill();
  }

  private onPlayerDied(by: string): void {
    this.lastKillerName = by;
    this.hud.killFeed(`${by} ▶ YOU`, 'death');
    // 부활은 없다. 쓰러지는 모습을 잠깐 보여 준 뒤 임무 실패로 끝난다
    this.state = 'dead';
    this.endAt = this.simTime + DEATH_CAM_SECONDS;
  }

  private endGame(victory: boolean, reason = ''): void {
    if (this.state === 'ended') return;
    this.state = 'ended';
    this.hud.setObjectiveMarker(null, this.camera);
    this.hud.setInteract(null);
    document.exitPointerLock();
    const s = this.player.stats;
    const acc = s.shots ? Math.round((s.hits / s.shots) * 100) : 0;
    const hsr = s.hits ? Math.round((s.headshots / s.hits) * 100) : 0;
    const elapsed = Math.round(this.simTime - this.startedAt);
    const label = this.ctx.difficulty.label;
    const sub = victory
      ? `임무 완수 — 제비가 스카이독을 벗어났다. 항로 기록은 무사히 전달되었다 · ${label}`
      : `임무 실패 — ${reason || '레이븐의 신호가 끊겼다'}. 항로 기록은 스카이독에 남았다 · ${label}`;
    this.hud.setEnd(victory, sub, [
      ['점수', String(this.score)],
      ['처치', String(s.kills)],
      ['사망', String(s.deaths)],
      ['명중률', `${acc}%`],
      ['헤드샷 비율', `${hsr}%`],
      ['최대 연속 처치', String(s.maxStreak)],
      ['펄스 로켓 / 치유 필드 / 궁', `${s.rockets} / ${s.fields} / ${s.ults}`],
      ['플레이 시간', `${Math.floor(elapsed / 60)}:${String(elapsed % 60).padStart(2, '0')}`],
    ]);
    this.hud.showOverlay('ov-end');
  }

  private onNoise(pos: Vector3, radius: number): void {
    for (const b of this.bots) {
      if (b.alive && b.position.distanceTo(pos) <= radius) b.hear(pos);
    }
  }

  // ---------- 루프 ----------

  private frame(t: number): void {
    requestAnimationFrame((n) => this.frame(n));
    const dt = Math.min(0.1, (t - this.lastFrame) / 1000 || 0);
    this.lastFrame = t;

    if (this.input.justPressed('F8')) this.setAutopilot(this.autopilot ? null : 'average');
    if (this.input.justPressed('F7') && this.post) {
      this.post.enabled = !this.post.enabled;
      this.perfChecked = true;
      this.hud.killFeed(this.post.enabled ? '후처리 ON' : '후처리 OFF');
    }
    if (this.input.justPressed('F3')) {
      this.debug = !this.debug;
      for (const b of this.bots) b.setDebug(this.debug);
      if (!this.debug) this.hud.clearBotLabels();
    }

    // 키 "방금 눌림"은 시뮬레이션 스텝이 실제로 소비한 뒤에만 지운다.
    // 렌더 프레임마다 지우면 스텝이 없는 프레임(고주사율 모니터)에서 점프·스킬 입력이 유실된다.
    let consumedInput = true;
    if (this.state === 'playing' || this.state === 'dead') {
      this.accumulator += dt;
      let steps = 0;
      while (this.accumulator >= FIXED_DT && steps < 5) {
        this.step(FIXED_DT);
        this.accumulator -= FIXED_DT;
        steps++;
      }
      consumedInput = steps > 0;
    } else {
      // 메뉴/일시정지: 마우스 누적 폐기
      this.input.consumeMouse();
    }

    this.touch?.setActive(this.state === 'playing');
    // 그림자 범위가 플레이어를 따라간다(맵이 길어져 고정 범위로는 다 덮지 못한다). 4m 단위로 옮겨 그림자가 떨리지 않게 한다
    const sp = this.player.position;
    const sx = Math.round(sp.x / 4) * 4;
    const sz = Math.round(sp.z / 4) * 4;
    this.sun.target.position.set(sx, 0, sz);
    this.sun.position.set(sx + 42, 40, sz + 16);
    // The control block cannot be seen from the landing pad (camera, not player: third person and the death cam move it)
    this.map.setBlockVisible(this.camera.position.z < -32);
    const inside = this.camera.position.z < -122.3 ? 1 : 0;
    this.indoor += (inside - this.indoor) * Math.min(1, dt * 5);
    this.hemi.intensity = FILL_OUT.hemi + (FILL_IN.hemi - FILL_OUT.hemi) * this.indoor;
    this.scene.environmentIntensity = FILL_OUT.env + (FILL_IN.env - FILL_OUT.env) * this.indoor;
    this.fx.camPos.copy(this.camera.position);
    this.fx.update(dt);
    if (this.post) {
      // 맞은 만큼 화면 충격(색수차·붉은 가장자리), 체력이 낮으면 채도가 빠진다
      const hp = this.player.hp;
      const inGame = this.state === 'playing' || this.state === 'dead';
      if (inGame && hp < this.lastHpSeen) this.post.hit((this.lastHpSeen - hp) / 50);
      this.lastHpSeen = hp;
      this.post.setHealth(!inGame ? 1 : this.state === 'dead' ? 0.15 : hp / this.player.maxHp);
      // 느린 기기 보호: 플레이 첫 4초쯤(240프레임)의 평균이 40fps에 못 미치면 후처리를 끈다. F7로 다시 켤 수 있다
      if (!this.perfChecked && this.post.enabled && this.state === 'playing' && dt > 0 && dt < 0.1 && document.visibilityState === 'visible') {
        this.perfFrames++;
        this.perfTime += dt;
        if (this.perfFrames >= 240) {
          this.perfChecked = true;
          if (this.perfTime / this.perfFrames > 1 / 40) {
            this.post.enabled = false;
            this.hud.killFeed('프레임이 낮아 후처리를 껐습니다 (F7로 다시 켜기)');
          }
        }
      }
    }
    if (this.debug && this.state !== 'menu') {
      const items = this.bots.filter((b) => b.alive).map((b) => ({ world: b.position.clone().setY(b.position.y + 2.1), text: b.debugText() }));
      this.hud.setBotLabels(items, this.camera);
      for (const b of this.bots) b.setDebug(true);
    }
    this.renderFrame();
    if (consumedInput) this.input.endFrame();
  }

  /**
   * 월드 패스 → 뷰모델 패스. 1인칭 총이 벽을 뚫고 보이지 않게 따로 그린다.
   * 후처리가 켜져 있으면 PostFx가 두 패스를 각자의 타깃에 그려 합친 뒤 블룸·화면 보정을 한다.
   * 꺼져 있으면 화면에 바로 그린다(월드 → 깊이 버퍼 비움 → 뷰모델).
   */
  private renderFrame(): void {
    if (this.post?.enabled) {
      this.post.render();
      return;
    }
    const r = this.renderer;
    this.drawWorld();
    r.autoClear = false;
    r.clearDepth();
    this.drawViewmodel();
    r.autoClear = true;
  }

  private drawWorld(): void {
    this.camera.layers.set(0);
    this.renderer.render(this.scene, this.camera);
  }

  private drawViewmodel(): void {
    const bg = this.scene.background;
    this.scene.background = null;
    // 뷰모델 전용 FOV: 가까운 총·팔의 원근 왜곡을 줄인다 (일반 FPS 관례)
    const worldFov = this.camera.fov;
    this.camera.fov = Player.VIEWMODEL_FOV;
    this.camera.updateProjectionMatrix();
    this.camera.layers.set(Player.VIEWMODEL_LAYER);
    this.renderer.render(this.scene, this.camera);
    this.camera.layers.set(0);
    this.camera.fov = worldFov;
    this.camera.updateProjectionMatrix();
    this.scene.background = bg;
  }

  /**
   * 셰이더 사전 컴파일: 효과·봇 모델 재질을 로딩 단계에서 한 번 컴파일해 전투 중 멈춤을 없앤다
   */
  private warmupShaders(a: LoadedAssets): void {
    const t0 = performance.now();
    let dummy: import('three').Object3D | null = null;
    const skinned = a.botRig?.scene ?? a.raven?.scene;
    if (skinned) {
      // 스킨드 메시 전용 셰이더 변형도 미리 컴파일
      dummy = SkeletonUtils.clone(skinned);
      dummy.position.set(0, -200, 0);
      this.scene.add(dummy);
      // 종류별 갑옷 색(채널 돌리기)은 셰이더가 따로다. 살아 있을 때(불투명)와 사라질 때(투명) 것을 모두 미리 컴파일한다
      for (const hue of ['rbg', 'brg'] as const) for (const transparent of [false, true]) {
        const v = SkeletonUtils.clone(skinned);
        v.traverse((o) => {
          const mesh = o as import('three').Mesh;
          if (!mesh.isMesh) return;
          const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
          const out = mats.map((orig) => {
            if (orig.name !== 'bot_detail') return orig;
            const mm = orig.clone();
            applyHueSwap(mm, hue);
            mm.transparent = transparent;
            return mm;
          });
          mesh.material = out.length === 1 ? out[0] : out;
        });
        dummy.add(v);
      }
    }
    this.fx.warmup(this.renderer, this.camera);
    if (dummy) this.scene.remove(dummy);
    console.info(`[Assets] shader warmup ${Math.round(performance.now() - t0)}ms`);
  }

  /** 오토파일럿 켜기/끄기 */
  setAutopilot(profile: keyof typeof AUTOPILOT_PROFILES | AutopilotProfile | null): void {
    if (!profile) {
      this.autopilot = null;
      this.hud.killFeed('오토파일럿 OFF');
      return;
    }
    const prof = typeof profile === 'string' ? AUTOPILOT_PROFILES[profile] : profile;
    this.autopilot = new Autopilot(this.ctx, prof);
    this.hud.killFeed(`오토파일럿 ON (${typeof profile === 'string' ? profile : 'custom'})`, 'hs');
  }

  private step(dt: number): void {
    this.simTime += dt;
    this.ctx.now = this.simTime;
    if (this.state === 'playing') {
      if (this.autopilot) {
        this.autopilot.objective = this.mission.goal();
        this.autopilot.think(dt);
        this.player.update(dt, this.autopilot);
        this.autopilot.endFrame();
      } else this.player.update(dt, this.input);
    }
    else {
      this.input.consumeMouse();
      this.player.updateDeathCam(dt);
      if (this.state === 'dead' && this.simTime >= this.endAt) this.endGame(false, `${this.lastKillerName}에게 쓰러졌다`);
    }
    this.assignAttackTokens();
    for (const b of this.bots) b.update(dt);
    for (const pr of this.projectiles) pr.update(dt);
    if (this.projectiles.some((p) => p.done)) this.projectiles = this.projectiles.filter((p) => !p.done);
    this.updatePacks(dt);
    this.mission.update(dt);
  }

  /** 공격 토큰 배분: 플레이어가 보이는 봇 중 가까운 순으로 난이도별 N명만 사격 허용 */
  private assignAttackTokens(): void {
    const n = this.ctx.difficulty.attackTokens;
    const p = this.player.position;
    const seeing = this.bots.filter((b) => b.alive && b.seesPlayer && !b.isBoss && !b.def.shot);
    seeing.sort((a, b) => a.position.distanceTo(p) - b.position.distanceTo(p));
    for (const b of this.bots) b.hasAttackToken = false;
    for (let i = 0; i < Math.min(n, seeing.length); i++) seeing[i].hasAttackToken = true;
  }

  private updatePacks(dt: number): void {
    for (const pk of this.packs) {
      pk.update(this.simTime, dt);
      if (!pk.active) continue;
      if (this.player.alive) {
        const healed = pk.tryPickup(this.player, this.simTime);
        if (healed > 0) {
          this.hud.healNumber(healed);
          this.hud.setHp(this.player.hp, this.player.maxHp);
          this.sfx.heal();
          continue;
        }
      }
      for (const b of this.bots) {
        if (b.alive && pk.tryPickup(b, this.simTime) > 0) break;
      }
    }
  }

  private lastKillerName = '???';
}
